'use strict';
// Analytic circle contacts for marbles. Walls keep Matter's polygon collision path.
(()=>{const{Collision,Pair}=Matter,polygonCollides=Collision.collides;Collision.collides=function(a,b,pairs){if(!a.plugin?.marble||!b.plugin?.marble)return polygonCollides(a,b,pairs);const dx=b.position.x-a.position.x,dy=b.position.y-a.position.y,sum=a.circleRadius+b.circleRadius;if(dx*dx+dy*dy>=sum*sum)return null;const pair=pairs?.table[Pair.id(a,b)];const c=pair?pair.collision:Collision.create(a.id<b.id?a:b,a.id<b.id?b:a);c.collided=true;a=c.bodyA;b=c.bodyB;const x=b.position.x-a.position.x,y=b.position.y-a.position.y,d=Math.hypot(x,y),nx=d>1e-8?x/d:1,ny=d>1e-8?y/d:0,depth=a.circleRadius+b.circleRadius-d;c.depth=depth;c.normal.x=-nx;c.normal.y=-ny;c.tangent.x=ny;c.tangent.y=-nx;c.penetration.x=-nx*depth;c.penetration.y=-ny*depth;const point=c._circleSupport||(c._circleSupport={x:0,y:0,index:0,body:b,isInternal:false});point.x=a.position.x+nx*(a.circleRadius-depth*.5);point.y=a.position.y+ny*(a.circleRadius-depth*.5);c.supports[0]=point;c.supports[1]=null;c.supportCount=1;return c}})();
